ALTER TABLE "programa_fidelidade_reservas" ADD CONSTRAINT "programa_fidelidade_reserva_valores_validos" CHECK (("programa_fidelidade_reservas"."modalidade" = 'desconto_monetario' AND "programa_fidelidade_reservas"."credito_em_centavos" > 0 AND "programa_fidelidade_reservas"."base_elegivel_em_centavos" >= "programa_fidelidade_reservas"."credito_em_centavos" AND "programa_fidelidade_reservas"."limite_aplicado_em_centavos" >= "programa_fidelidade_reservas"."credito_em_centavos" AND "programa_fidelidade_reservas"."valor_minimo_pagamento_em_centavos" > 0) OR ("programa_fidelidade_reservas"."modalidade" = 'recompensa' AND "programa_fidelidade_reservas"."credito_em_centavos" = 0 AND "programa_fidelidade_reservas"."base_elegivel_em_centavos" = 0 AND "programa_fidelidade_reservas"."limite_aplicado_em_centavos" = 0 AND "programa_fidelidade_reservas"."valor_minimo_pagamento_em_centavos" = 0));